import SwiftUI
import ComedorCore

enum Style {static let navy=Color(red:0.055,green:0.12,blue:0.22),teal=Color(red:0,green:0.49,blue:0.44),paper=Color(red:0.94,green:0.96,blue:0.98)}
@main struct ComedorControlApp:App {
 @StateObject private var model=AppModel();@Environment(\.scenePhase) var phase
 var body:some Scene{WindowGroup{RootView().environmentObject(model).tint(Style.teal).preferredColorScheme(.light).onChange(of:phase){value in if value == .background{model.lock()}}}}
}
enum Screen:String,CaseIterable {case home="Inicio",scan="Escanear",workers="Trabajadores",visitors="Visitantes",reports="Reportes",network="Conexión",license="Licencia";var icon:String{switch self{case .home:return "square.grid.2x2";case .scan:return "qrcode.viewfinder";case .workers:return "person.2";case .visitors:return "person.badge.plus";case .reports:return "chart.bar.xaxis";case .network:return "arrow.triangle.2.circlepath";case .license:return "checkmark.shield"}}}
struct RootView:View {
 @EnvironmentObject var model:AppModel;@Environment(\.scenePhase) var phase
 @State private var screen=Screen.home
 @State private var activation=false
 var body:some View{Group{
  if !model.fatal.isEmpty{VStack(spacing:24){Image(systemName:"lock.doc").font(.system(size:56));Text(model.fatal).multilineTextAlignment(.center)}.padding()}
  else if !model.unlocked{VStack(spacing:24){Image(systemName:"fork.knife.circle.fill").font(.system(size:78)).foregroundStyle(Style.teal);Text("Control del comedor").font(.largeTitle.bold());Text("SOBOCE + FRIGOR").foregroundStyle(.secondary);Button("Desbloquear"){Task{await model.unlock()}}.buttonStyle(PrimaryButton());Text(model.message).font(.footnote).multilineTextAlignment(.center)}.padding(30).task{await model.unlock()}}
  else{NavigationStack{ScrollView{VStack(alignment:.leading,spacing:22){header
   if model.company==nil{welcome}else{
    companyPicker
    if !model.message.isEmpty{Label(model.message,systemImage:model.busy ? "arrow.triangle.2.circlepath":"info.circle").font(.footnote).foregroundStyle(.secondary).accessibilityIdentifier("connectionMessage")}
    if let c=model.company{let warning=License.warning(c.license,config:c.profile.license);if !warning.isEmpty{Label(warning,systemImage:"clock").font(.footnote).padding(12).background(Color.orange.opacity(0.12),in:RoundedRectangle(cornerRadius:14))}}
    switch screen{case .home:home;case .scan:ScanPanel();case .workers:WorkersPanel();case .visitors:VisitorPanel();case .reports:ReportsPanel();case .network:network;case .license:license}
   }
  }.padding(22)}.background(Style.paper).toolbar{ToolbarItem(placement:.navigationBarLeading){Text("COLBERT / COMEDOR").font(.caption.weight(.bold)).foregroundStyle(Style.teal)};ToolbarItem(placement:.navigationBarTrailing){Menu{ForEach(Screen.allCases,id:\.self){item in Button{screen=item}label:{Label(item.rawValue,systemImage:item.icon)}};Divider();Button{activation=true}label:{Label("Agregar empresa",systemImage:"plus.circle")};Button{model.lock()}label:{Label("Bloquear pantalla",systemImage:"lock")}}label:{Image(systemName:"line.3.horizontal").font(.title2)}.accessibilityIdentifier("mainMenu")}}
   .sheet(isPresented:$activation){ActivationView()}
   .task{while !Task.isCancelled{if phase == .active && model.unlocked && screen != .scan{await model.synchronize()};try? await Task.sleep(nanoseconds:30_000_000_000);if Task.isCancelled{break}}}
  }}
 }.overlay{if phase != .active{Style.navy.ignoresSafeArea().overlay{Label("Comedor · contenido protegido",systemImage:"lock.fill").foregroundStyle(.white)}}}}
 var header:some View{VStack(alignment:.leading,spacing:7){Text(screen == .home ? "Cada entrega,\nbajo control.":screen.rawValue).font(.system(size:32,weight:.bold,design:.rounded)).foregroundStyle(Style.navy);Text(screen == .home ? "El servicio de hoy, en tus manos.":"SOBOCE y FRIGOR · Control de encargados").font(.subheadline).foregroundStyle(.secondary)}}
 var welcome:some View{VStack(alignment:.leading,spacing:20){Image(systemName:"qrcode.viewfinder").font(.system(size:65)).foregroundStyle(Style.teal);Text("Bienvenido al equipo").font(.title2.bold());Text("Jesús te entrega un QR privado para activar cada empresa. Después de la primera sincronización podrás registrar comidas sin conexión.");Button("Activar una empresa"){activation=true}.buttonStyle(PrimaryButton());Text("La aplicación protege el acceso con el código o biometría del iPhone. El QR de activación es solo para encargados autorizados.").font(.footnote).foregroundStyle(.secondary)}.card()}
 var companyPicker:some View{VStack(alignment:.leading,spacing:12){HStack{ForEach(model.state.companies.keys.sorted(),id:\.self){id in Button{model.select(id)}label:{Text(id.uppercased()).font(.subheadline.bold()).frame(maxWidth:.infinity).padding(.vertical,12).background(model.state.selected==id ? Style.navy:Color.white,in:Capsule()).foregroundStyle(model.state.selected==id ? Color.white:Style.navy)}.disabled(model.busy)}};HStack{Image(systemName:"building.2").foregroundStyle(Style.teal);Picker("Planta",selection:$model.plant){ForEach(model.company?.plants ?? [],id:\.self){Text($0).tag($0)}}.pickerStyle(.menu).disabled(model.busy);Spacer()}.padding(.horizontal,8).background(Color.white,in:RoundedRectangle(cornerRadius:14))}}
 var home:some View{VStack(alignment:.leading,spacing:20){let rows=model.records(date:Date(),monthly:false,allPlants:false)
  HStack(spacing:12){Metric(title:"Entregas hoy",value:"\(rows.count)",icon:"fork.knife");Metric(title:"Trabajadores",value:"\(Set(rows.map{$0["persona"].s}).count)",icon:"person.2.fill")}
  Text("¿Qué vamos a servir?").font(.title3.bold());MealPicker()
  Button{screen = .scan}label:{Label("Comenzar a escanear",systemImage:"qrcode.viewfinder")}.buttonStyle(PrimaryButton()).accessibilityIdentifier("startScan")
  if let c=model.company{Label(c.permitted ? "Permiso vigente":"Comprueba el permiso en Licencia",systemImage:c.permitted ? "checkmark.shield.fill":"exclamationmark.shield").font(.subheadline).foregroundStyle(c.permitted ? Style.teal:Color.orange);if c.pending != nil{Label("Hay una entrega sin confirmar. Abre el escáner para comprobarla.",systemImage:"exclamationmark.triangle.fill").foregroundStyle(.red)};HStack{Text("\(c.outbox.count) entregas por compartir");Spacer();Button("Sincronizar"){Task{await model.synchronize()}}.disabled(model.busy)}.font(.footnote)}
  VStack(alignment:.leading,spacing:12){Text("Últimas entregas").font(.headline);if rows.isEmpty{Text("Las entregas aparecerán aquí al registrar el primer QR.").foregroundStyle(.secondary)};ForEach(Array(rows.prefix(5).enumerated()),id:\.offset){_,r in RecordRow(record:r)}}.card()
 }}
 var network:some View{VStack(alignment:.leading,spacing:18){Label("iPhone conectado como encargado",systemImage:"iphone.gen3.radiowaves.left.and.right").font(.headline);Text("Comparte personas y entregas con el teléfono Android que tiene el servidor activo. El iPhone conserva sus datos aunque no haya internet.");if let c=model.company{LabeledContent("Última sincronización",value:c.lastSync>0 ? Wire.date(c.lastSync):"Pendiente");LabeledContent("Entregas pendientes",value:"\(c.outbox.count)");LabeledContent("Altas pendientes",value:"\(c.rosterOutbox.count)");Text(c.profile.url).font(.footnote).textSelection(.enabled)};Button("Sincronizar ahora"){Task{await model.synchronize()}}.buttonStyle(PrimaryButton()).disabled(model.busy);Text("Para el intercambio, el servidor Android debe usar la versión 1.14 o posterior. Durante el uso sin conexión se detectan las repeticiones conocidas por este iPhone; otros equipos pueden tener entregas aún no compartidas.").font(.footnote).foregroundStyle(.secondary);OperatorEditor()}.card()}
 var license:some View{VStack(alignment:.leading,spacing:18){if let c=model.company{Image(systemName:c.permitted ? "checkmark.shield.fill":"lock.shield").font(.system(size:60)).foregroundStyle(c.permitted ? Style.teal:.orange);Text(c.permitted ? "Tu acceso está vigente":"Validar acceso").font(.title2.bold());if let l=c.license{Text("Vigente hasta \(Wire.date(l.claims["expiresAt"].i))")};Text("Un permiso mensual verificado funciona hasta su vencimiento, aunque el servidor de cobros esté apagado. Los permisos temporales duran como máximo 24 horas desde su validación.");Button("Comprobar permiso"){Task{await model.refreshLicense()}}.buttonStyle(PrimaryButton()).disabled(model.busy);Text("Jesús administra la autorización de tu empresa. La app avisa durante los últimos dos días para renovar con anticipación.").font(.footnote).foregroundStyle(.secondary)}}.card()}
}
struct PrimaryButton:ButtonStyle{func makeBody(configuration:Configuration)->some View{configuration.label.font(.headline).frame(maxWidth:.infinity).padding(.vertical,18).foregroundStyle(.white).background(Style.teal.opacity(configuration.isPressed ? 0.7:1),in:RoundedRectangle(cornerRadius:18))}}
extension View{func card()->some View{padding(20).frame(maxWidth:.infinity,alignment:.leading).background(Color.white,in:RoundedRectangle(cornerRadius:22))}}
struct Metric:View{let title:String,value:String,icon:String;var body:some View{VStack(alignment:.leading,spacing:12){Image(systemName:icon).foregroundStyle(Style.teal);Text(value).font(.system(size:34,weight:.bold,design:.rounded)).foregroundStyle(Style.navy);Text(title).font(.caption).foregroundStyle(.secondary)}.frame(maxWidth:.infinity,alignment:.leading).card()}}
struct MealPicker:View{@EnvironmentObject var model:AppModel;let symbols=["sunrise.fill","sun.max.fill","moon.stars.fill","leaf.fill"];var body:some View{LazyVGrid(columns:[GridItem(.flexible()),GridItem(.flexible())],spacing:12){ForEach(Array(Ledger.meals.enumerated()),id:\.offset){i,m in Button{model.meal=m}label:{HStack{Image(systemName:symbols[i]);Text(m.capitalized);Spacer();if model.meal==m{Image(systemName:"checkmark.circle.fill")}}.font(.subheadline.bold()).padding(16).background(model.meal==m ? Style.teal:Color.white,in:RoundedRectangle(cornerRadius:16)).foregroundStyle(model.meal==m ? Color.white:Style.navy)}.disabled(model.busy)}}}
}
struct RecordRow:View{let record:J;var body:some View{HStack(spacing:12){Image(systemName:"checkmark").font(.headline).foregroundStyle(Style.teal).frame(width:34,height:34).background(Style.teal.opacity(0.1),in:Circle());VStack(alignment:.leading,spacing:3){Text(record["nombre"].s).font(.subheadline.bold());Text("\(record["comida"].s.capitalized) · \(record["planta"].s)").font(.caption).foregroundStyle(.secondary)};Spacer();Text(record["hora"].s.prefix(5)).font(.caption.monospacedDigit())}.padding(.vertical,5)}}
struct OperatorEditor:View{@EnvironmentObject var model:AppModel;@State var name="";@State var error="";var body:some View{VStack(alignment:.leading){Text("Nombre del encargado").font(.headline);TextField("Tu nombre",text:$name).textFieldStyle(.roundedBorder);Button("Guardar nombre"){do{try model.rename(name);error="Guardado."}catch{self.error=error.localizedDescription}};Text(error).font(.footnote)}.onAppear{name=model.state.operatorName}}}
struct ActivationView:View{@EnvironmentObject var model:AppModel;@Environment(\.dismiss) var dismiss;@Environment(\.scenePhase) var phase;@State var waiting=false;@State var error=""
 var body:some View{NavigationStack{VStack(spacing:22){Text("Activar empresa").font(.title.bold());Text("Escanea el QR privado que te entrega Jesús. Solo se necesita una vez por empresa.").multilineTextAlignment(.center);CameraView(active:!waiting && phase == .active,receive:{qr in waiting=true;Task{do{try await model.activate(qr);dismiss()}catch{self.error=error.localizedDescription;waiting=false}}},failure:{error=$0}).clipShape(RoundedRectangle(cornerRadius:24)).overlay{RoundedRectangle(cornerRadius:24).stroke(Style.teal,lineWidth:4)};if waiting{ProgressView("Activando…")};Text(error).font(.footnote).foregroundStyle(.red)}.padding(24).toolbar{ToolbarItem(placement:.cancellationAction){Button("Cerrar"){dismiss()}}}}}
}
